import json
import math


class Symbol:
    def __init__(self, name):
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        if not name:
            raise ValueError("name must not be empty")
        allowed = all(c.isascii() and (c.isalnum() or c in "_-." ) for c in name)
        if not allowed or not (name[0].isascii() and (name[0].isalpha() or name[0] == "_")):
            raise ValueError("invalid symbol name")
        self.name = name


class TokenSequence:
    def __init__(self, first=None):
        self._values = []
        if first is not None:
            self.append(first)

    def append(self, value):
        if isinstance(value, bool) or not isinstance(value, (int, float, str, Symbol)):
            raise TypeError("unsupported token")
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError("float must be finite")
        self._values.append(value)
        return self

    @staticmethod
    def _encode(value):
        if isinstance(value, Symbol):
            return "@" + value.name
        if isinstance(value, str):
            return json.dumps(value, ensure_ascii=False)
        return str(value)

    def __bytes__(self):
        body = " ".join(self._encode(value) for value in self._values)
        return ("{" + body + "}").encode("utf-8")

